<script setup>
import { computed, ref, watch, toRefs } from 'vue';import {readingSections,listeningSections,writingPrompts,speakingPrompts} from '../data/content';import {useLocal} from '../composables/useLocal';import {useRecorder} from '../composables/useRecorder';
const props=defineProps({voice:Object,settings:Object,initialSkill:{type:String,default:'reading'}});const {voice,settings}=toRefs(props);const skill=ref(props.initialSkill),started=ref(false),section=ref(0),answers=useLocal('nahui-exam-answers',{}),writing=useLocal('nahui-writing',{}),selectedPrompt=ref(0),rec=useRecorder();const feedback=ref(false);const currentReading=computed(()=>readingSections[section.value]);const currentListening=computed(()=>listeningSections[section.value]);const wordCount=computed(()=>((writing.value[writingPrompts[selectedPrompt.value].id]||'').trim().match(/[\w’'-]+/g)||[]).length);function score(items,prefix){return items.reduce((n,_,i)=>n+(answers.value[prefix+i]===_.answer?1:0),0)}function reset(){started.value=false;feedback.value=false;section.value=0}function chooseSkill(s){skill.value=s;reset();history.replaceState({},'',`/practice/${s}`);if(s==='speaking')rec.refresh()}watch(()=>props.initialSkill,s=>{if(['reading','listening','writing','speaking'].includes(s)){skill.value=s;reset()}},{immediate:true})
</script>
<template><section class="panel"><div class="eyebrow">Simulador B2 local</div><h1>Cuatro habilidades</h1><p class="lede">Práctica independiente inspirada en la estructura pública de la guía. El diagnóstico es orientativo, no oficial.</p><div class="skill-tabs" role="tablist"><button v-for="s in ['reading','listening','writing','speaking']" :key="s" :class="{active:skill===s}" @click="chooseSkill(s)">{{s}}</button></div>
<div v-if="!started" class="start-card"><h2>{{skill}}</h2><p v-if="skill==='reading'">2 textos, 15 reactivos. La guía orientativa contempla 30 minutos.</p><p v-else-if="skill==='listening'">2 audios sintetizados, 15 reactivos. En práctica puedes repetirlos.</p><p v-else-if="skill==='writing'">Elige una de dos tareas, escribe entre 120 y 140 palabras y usa la lista de revisión.</p><p v-else>Entrevista guiada, grabación local y autoevaluación de inteligibilidad y fluidez.</p><button class="aero-button primary" @click="started=true">Comenzar práctica</button></div>
<div v-else-if="skill==='reading'" class="exam-grid"><article class="paper"><div class="section-nav"><button v-for="(_,i) in readingSections" @click="section=i" :class="{active:section===i}">Texto {{i+1}}</button></div><h2>{{currentReading.title}}</h2><p class="reading-text">{{currentReading.text}}</p></article><aside class="questions"><div v-for="(q,i) in currentReading.questions" class="question"><b>{{i+1}}. {{q.q}}</b><label v-for="(o,j) in q.options" :class="feedback?{'right':j===q.answer,'wrong':answers[currentReading.id+i]===j&&j!==q.answer}:{}"><input type="radio" :name="currentReading.id+i" :value="j" v-model="answers[currentReading.id+i]"> {{o}}</label></div><button class="aero-button" @click="feedback=!feedback">{{feedback?'Ocultar':'Revisar'}} respuestas</button><p v-if="feedback"><b>Resultado de esta sección: {{score(currentReading.questions,currentReading.id)}} / {{currentReading.questions.length}}</b></p></aside></div>
<div v-else-if="skill==='listening'" class="exam-grid"><article class="paper audio-card"><div class="section-nav"><button v-for="(_,i) in listeningSections" @click="section=i" :class="{active:section===i}">Audio {{i+1}}</button></div><h2>{{currentListening.title}}</h2><div class="orb">♫</div><button class="aero-button primary" @click="voice.speak(currentListening.script,settings.variant==='gb'?'en-GB':'en-US',.88)">Reproducir audio</button><p>{{props.voice.status}}</p><details v-if="settings.practice"><summary>Mostrar transcripción de práctica</summary><p>{{currentListening.script}}</p></details></article><aside class="questions"><div v-for="(q,i) in currentListening.questions" class="question"><b>{{i+1}}. {{q.q}}</b><label v-for="(o,j) in q.options" :class="feedback?{'right':j===q.answer,'wrong':answers[currentListening.id+i]===j&&j!==q.answer}:{}"><input type="radio" :name="currentListening.id+i" :value="j" v-model="answers[currentListening.id+i]"> {{o}}</label></div><button class="aero-button" @click="feedback=!feedback">{{feedback?'Ocultar':'Revisar'}} respuestas</button><p v-if="feedback"><b>Resultado: {{score(currentListening.questions,currentListening.id)}} / {{currentListening.questions.length}}</b></p></aside></div>
<div v-else-if="skill==='writing'" class="writing"><div class="prompt-picker"><button v-for="(p,i) in writingPrompts.slice(0,2)" @click="selectedPrompt=i" :class="{active:selectedPrompt===i}">Opción {{i+1}} · {{p.type}}</button></div><article class="paper"><span class="tag">Registro {{writingPrompts[selectedPrompt].register}}</span><h2>{{writingPrompts[selectedPrompt].type}}</h2><p>{{writingPrompts[selectedPrompt].prompt}}</p><p><b>Use 120–140 words.</b></p></article><textarea v-model="writing[writingPrompts[selectedPrompt].id]" rows="14" placeholder="Write your answer here..."></textarea><div class="wordbar" :class="{ok:wordCount>=120&&wordCount<=140}">{{wordCount}} palabras · Guardado automáticamente</div><div class="checklist"><label><input type="checkbox"> Cumplí la tarea y el registro</label><label><input type="checkbox"> Organicé las ideas con conectores</label><label><input type="checkbox"> Revisé gramática, vocabulario, ortografía y puntuación</label><label><input type="checkbox"> Estoy entre 120 y 140 palabras</label></div></div>
<div v-else class="speaking"><div class="notice"><b>Contexto seguro:</b> {{rec.secure?'Sí':'No'}} · <b>Grabación:</b> {{rec.supported?'Disponible':'No disponible'}} · {{rec.status}}</div><select v-model="rec.deviceId"><option value="">Micrófono predeterminado</option><option v-for="d in rec.devices" :value="d.deviceId">{{d.label||'Micrófono'}}</option></select><button class="aero-button" @click="rec.test">Probar micrófono</button><p class="error" v-if="rec.error">{{rec.error}}</p><div class="prompt-stack"><article v-for="(p,i) in speakingPrompts.slice(0,3)" class="paper"><small>Pregunta {{i+1}}</small><h2>{{p}}</h2><button class="aero-button" @click="voice.speak(p,settings.variant==='gb'?'en-GB':'en-US')">Escuchar</button></article></div><div class="recorder"><button v-if="!rec.recording" class="aero-button primary" @click="rec.start">● Grabar respuesta</button><button v-else class="aero-button danger" @click="rec.stop">■ Detener · {{rec.elapsed}} s</button><div class="meter"><span :style="{width:rec.level+'%'}"></span></div><audio v-if="rec.audioUrl" :src="rec.audioUrl" controls></audio></div><div class="checklist"><b>Autoevaluación orientativa</b><label><input type="checkbox"> Mis ideas fueron comprensibles</label><label><input type="checkbox"> Sostuve la respuesta con razones o ejemplos</label><label><input type="checkbox"> Mi pronunciación no impidió la comunicación</label><label><input type="checkbox"> Mantuve una fluidez razonable aunque hice pausas</label></div></div>
</section></template>
